"""One owned Windows source batch, then one native batch; UIA/path/lease guards."""
from pathlib import Path
import argparse,base64,hashlib,io,json,time,uuid,zipfile
from driver import ps,q
r=Path(__file__).resolve().parents[2];p=argparse.ArgumentParser();p.add_argument('action',choices=['source','native']);p.add_argument('manifest',type=Path);a=p.parse_args();m=json.loads(a.manifest.read_text());stage=json.loads((a.manifest.parent/'windows-stage.json').read_text());assert m['owner']=='root' and m['component']=='progressmeter' and m['runtime']=='win-x64' and stage['selfContained'];assert json.loads((r/'docs/replica/ENVIRONMENT_LEASE.json').read_text())['resources']['windows']['owner']=='root'
base="$app=Join-Path (Join-Path $env:TEMP "+q(stage['guestFolder'])+") 'app';"
find="function FindOwned($native){$rows=@([System.Windows.Automation.AutomationElement]::RootElement.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition)|Where-Object{if($native){$_.Current.Name-eq 'Replica ProgressMeter verification'-and(Get-Process -Id $_.Current.ProcessId).Path-eq ($app+'\\ReplicaProbe.exe')}else{$_.Current.Name.StartsWith('ProgressMeter · original isolation')-and(Get-Process -Id $_.Current.ProcessId -ErrorAction SilentlyContinue).Path-like '*\\Microsoft\\Edge\\Application\\msedge.exe'}});if($rows.Count-gt1){throw 'Duplicate owned window'};if($rows.Count-eq1){return $rows[0]};return $null};"
wait="function AwaitOwned($native){$end=[DateTime]::UtcNow.AddSeconds(10);do{$w=FindOwned $native;if($null-ne$w){return $w};Start-Sleep -Milliseconds 50}while([DateTime]::UtcNow-lt$end);throw 'Owned window missing'};"
invoke="function InvokeOwned($w,$id,$done){$end=[DateTime]::UtcNow.AddSeconds(10);do{$b=$w.FindFirst([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.PropertyCondition]::new([System.Windows.Automation.AutomationElement]::AutomationIdProperty,$id));if($null-ne$b){break};Start-Sleep -Milliseconds 50}while([DateTime]::UtcNow-lt$end);if($null-eq$b-or!$b.Current.IsEnabled){throw 'Owned measurement control missing'};$b.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke();do{if($b.Current.Name-eq$done){return};Start-Sleep -Milliseconds 50}while([DateTime]::UtcNow-lt$end);throw 'Fresh source result missing'};"
peer="function ReadMeters($w){$meters=@($w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.PropertyCondition]::new([System.Windows.Automation.AutomationElement]::ControlTypeProperty,[System.Windows.Automation.ControlType]::ProgressBar)));if($meters.Count-ne30){throw 'Thirty actual ProgressBars required'};@($meters|ForEach-Object{$pv=$null;$ok=$_.TryGetCurrentPattern([System.Windows.Automation.RangeValuePattern]::Pattern,[ref]$pv);[pscustomobject]@{id=$_.Current.AutomationId;name=$_.Current.Name;focusable=$_.Current.IsKeyboardFocusable;children=$_.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition).Count;rangeAvailable=$ok;value=if($ok){$pv.Current.Value}else{$null};minimum=if($ok){$pv.Current.Minimum}else{$null};maximum=if($ok){$pv.Current.Maximum}else{$null};readOnly=if($ok){$pv.Current.IsReadOnly}else{$null}}})};"
capture="Add-Type -AssemblyName System.Drawing;Add-Type 'using System;using System.Runtime.InteropServices;public static class MeterCapture{[DllImport(\"user32.dll\")]public static extern bool SetForegroundWindow(IntPtr h);[DllImport(\"user32.dll\")]public static extern IntPtr GetForegroundWindow();}';function CaptureOwned($w,$file){[MeterCapture]::SetForegroundWindow([IntPtr]$w.Current.NativeWindowHandle)|Out-Null;Start-Sleep -Milliseconds 150;if([MeterCapture]::GetForegroundWindow().ToInt64()-ne$w.Current.NativeWindowHandle){throw 'Exact capture foreground missing'};$rect=$w.Current.BoundingRectangle;if($rect.Width-lt500-or$rect.Width-gt4000-or$rect.Height-lt300-or$rect.Height-gt2400){throw 'Owned capture geometry rejected'};$bmp=[Drawing.Bitmap]::new([int]$rect.Width,[int]$rect.Height);$g=[Drawing.Graphics]::FromImage($bmp);try{$g.CopyFromScreen([int]$rect.Left,[int]$rect.Top,0,0,$bmp.Size);$bmp.Save($file,[Drawing.Imaging.ImageFormat]::Png)}finally{$g.Dispose();$bmp.Dispose()}};"
if a.action=='source':
 paths=[r/f'docs/replica/source/root-progressmeter-windows-{s}.json' for s in ['source','input','control-ready']];prior=[x.stat().st_mtime_ns if x.exists() else 0 for x in paths]
 code=base+find+wait+invoke+peer+capture+"if($null-ne(FindOwned $false)){throw 'Source already open; inspect instead'};Start-Process msedge.exe -ArgumentList @('--new-window','http://10.211.55.2:8768/progressmeter.html?os=windows');$w=AwaitOwned $false;InvokeOwned $w 'progressmeter-record' 'Recorded ProgressMeter';InvokeOwned $w 'progressmeter-timing' 'Measured transitions';InvokeOwned $w 'progressmeter-lifecycle' 'Lifecycle recorded';$rows=ReadMeters $w;$png=Join-Path $app 'source-frame.png';CaptureOwned $w $png;[pscustomobject]@{rows=$rows;frame=[Convert]::ToBase64String([IO.File]::ReadAllBytes($png))}|ConvertTo-Json -Depth 8 -Compress;"
 v=json.loads(ps(code,timeout=60));assert all(x.exists()and x.stat().st_mtime_ns>old for x,old in zip(paths,prior));out=a.manifest.parent/'actual-windows';out.mkdir(exist_ok=True);(out/'source-frame.png').write_bytes(base64.b64decode(v.pop('frame')));(out/'source-ax.json').write_text(json.dumps(v,indent=2)+'\n');print('Fresh source30/timing18/lifecycle7/AX30/capture; one guest batch')
else:
 nonce=uuid.uuid4().hex;out=a.manifest.parent/'actual-windows';out.mkdir(exist_ok=True);data=(r/'docs/replica/source/progressmeter-cases.json').read_bytes();served='root-progressmeter-'+nonce+'-actual-cases.json';(r/'artifacts/replica/windows-download'/served).write_bytes(data)
 code=base+find+wait+peer+capture+"if($null-ne(FindOwned $true)){throw 'Native already open; inspect instead'};$out=Join-Path $app "+q('actual-'+nonce)+";New-Item -ItemType Directory $out -Force|Out-Null;$ProgressPreference='SilentlyContinue';$cases=Join-Path $out 'cases.json';Invoke-WebRequest -UseBasicParsing "+q('http://10.211.55.2:8768/'+served)+" -OutFile $cases;if((Get-FileHash $cases -Algorithm SHA256).Hash-ne "+q(hashlib.sha256(data).hexdigest().upper())+"){throw 'Cases hash mismatch'};if((Get-FileHash ($app+'\\ReplicaProbe.dll') -Algorithm SHA256).Hash-ne "+q(m['binarySha256'].upper())+"){throw 'Binary mismatch'};Remove-Item Env:DBMV_HEADLESS,Env:DBMV_HEADLESS_SCALE -ErrorAction SilentlyContinue;$p=Start-Process ($app+'\\ReplicaProbe.exe') -ArgumentList @('--progressmeter-window',$cases,$out) -WorkingDirectory $app -PassThru;$w=AwaitOwned $true;$end=[DateTime]::UtcNow.AddSeconds(10);do{if(Test-Path ($out+'\\progressmeter-native.json')){break};Start-Sleep -Milliseconds 50}while([DateTime]::UtcNow-lt$end);if(!(Test-Path ($out+'\\progressmeter-lifecycle.json'))){throw 'Native batch incomplete'};[pscustomobject]@{pid=$p.Id;rows=@(ReadMeters $w)}|ConvertTo-Json -Depth 8|Set-Content -Encoding UTF8 ($out+'\\native-ax.json');CaptureOwned $w ($out+'\\native-frame.png');$w.GetCurrentPattern([System.Windows.Automation.WindowPattern]::Pattern).Close();$sw=FindOwned $false;if($null-ne$sw){$sw.GetCurrentPattern([System.Windows.Automation.WindowPattern]::Pattern).Close()};$end=[DateTime]::UtcNow.AddSeconds(5);do{$n=@(Get-Process -Name ReplicaProbe -ErrorAction SilentlyContinue|Where-Object{$_.Path-eq($app+'\\ReplicaProbe.exe')}).Count;if($n-eq0){break};Start-Sleep -Milliseconds 50}while([DateTime]::UtcNow-lt$end);$s=if($null-ne(FindOwned $false)){1}else{0};if($n-ne0-or$s-ne0){throw 'Exact cleanup failed'};[pscustomobject]@{nativeProcess=$n;sourceWindow=$s;nativePath=$app+'\\ReplicaProbe.exe'}|ConvertTo-Json|Set-Content -Encoding UTF8 ($out+'\\cleanup.json');Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=Join-Path $app "+q('actual-'+nonce+'.zip')+";[IO.Compression.ZipFile]::CreateFromDirectory($out,$zip);[Convert]::ToBase64String([IO.File]::ReadAllBytes($zip));"
 raw=base64.b64decode(ps(code,timeout=60));
 with zipfile.ZipFile(io.BytesIO(raw))as z:
  for n in z.namelist():
   assert Path(n).name==n
   if n.endswith('.json'):(out/n).write_text(z.read(n).decode('utf-8-sig'))
   else:(out/n).write_bytes(z.read(n))
 (out/'environment.json').write_text(json.dumps({'headless':False,'manifest':str(a.manifest.resolve()),'binarySha256':m['binarySha256'],'stage':stage,'batch':nonce,'rows':30,'timing':18,'lifecycle':7,'AX':30,'capture':'exact foreground scoped screen'},indent=2)+'\n');print(out)
